@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Airbnb DNA — warm white, coral accent, very rounded, soft diffuse shadows */
.theme-airbnb-dna {
  --bg: oklch(0.995 0.003 60);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.972 0.006 60);
  --fg: oklch(0.252 0 0);
  --fg-muted: oklch(0.55 0.012 40);
  --accent: oklch(0.658 0.231 17.1);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.55 0.13 340);
  --line: oklch(0.9 0.006 60);
  --success: oklch(0.62 0.14 160);
  --warning: oklch(0.8 0.15 80);
  --danger: oklch(0.58 0.22 25);

  --radius: 0.875rem;
  --radius-sm: 0.625rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 2px 6px oklch(0.3 0.02 40 / 8%);
  --shadow-2: 0 6px 20px oklch(0.3 0.02 40 / 12%);
  --shadow-3: 0 16px 40px oklch(0.3 0.02 40 / 18%);
  --glow: 0 0 0 2px color-mix(in oklab, var(--fg) 85%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Plus Jakarta Sans", sans-serif;
  --font-body: "Plus Jakarta Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-airbnb-dna h1,
.theme-airbnb-dna h2,
.theme-airbnb-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 700;
}

.theme-airbnb-dna button {
  transition: transform 140ms ease, box-shadow 140ms ease;
}

.theme-airbnb-dna button:hover {
  transform: scale(1.02);
}

/* signature */
.theme-airbnb-dna { --font-ui: var(--font-display); }
.theme-airbnb-dna h1 { font-weight: 600; letter-spacing: -0.02em; }
.theme-airbnb-dna button:hover { transform: scale(1.02); }

/* depth */
.theme-airbnb-dna thead th { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-airbnb-dna td { border-bottom: 1px solid color-mix(in oklab, var(--line) 60%, transparent); }
.theme-airbnb-dna tbody tr { transition: background 140ms ease; }
.theme-airbnb-dna tbody tr:hover { background: var(--surface-2); }
.theme-airbnb-dna input, .theme-airbnb-dna select { border-radius: var(--radius-pill); border: 1px solid var(--line); transition: border-color 140ms ease, box-shadow 140ms ease; }
.theme-airbnb-dna textarea { border-radius: var(--radius); border: 1px solid var(--line); }
.theme-airbnb-dna input:focus-visible, .theme-airbnb-dna select:focus-visible, .theme-airbnb-dna textarea:focus-visible { outline: none; border-color: var(--fg); box-shadow: var(--shadow-2); }
.theme-airbnb-dna a { color: var(--fg); text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
.theme-airbnb-dna a:hover { color: var(--accent); }
.theme-airbnb-dna ::selection { background: color-mix(in oklab, var(--accent) 22%, white); }
.theme-airbnb-dna ::-webkit-scrollbar { width: 10px; }
.theme-airbnb-dna ::-webkit-scrollbar-track { background: var(--bg); }
.theme-airbnb-dna ::-webkit-scrollbar-thumb { background: var(--line); border-radius: 999px; border: 2px solid var(--bg); }
.theme-airbnb-dna kbd { font-family: var(--font-mono); font-size: 0.72em; background: var(--surface-2); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 0.5em; padding: 0.1em 0.45em; }
.theme-airbnb-dna .label-caps { font-weight: 600; color: var(--fg-muted); }
.theme-airbnb-dna .themed-border { border-color: var(--line); }
.theme-airbnb-dna button:active { transform: scale(0.97); }

/* alt mode: warm charcoal night — Airbnb keeps its warmth after dark */
.theme-airbnb-dna.alt-mode {
  --bg: oklch(0.165 0.008 45.0);
  --surface: oklch(0.205 0.008 45.0);
  --surface-2: oklch(0.245 0.008 45.0);
  --fg: oklch(0.965 0.008 60);
  --fg-muted: oklch(0.72 0.015 50);
  --accent: oklch(0.688 0.220 17.1);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-airbnb-dna.alt-mode ::selection { background: oklch(0.42 0.14 17.1); }
.theme-airbnb-dna.alt-mode input, .theme-airbnb-dna.alt-mode select, .theme-airbnb-dna.alt-mode textarea { background: var(--surface); color: var(--fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
